contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account) public {
        // The contract address that performs liquidation checks (msg.sender must be
        // the collateral contract for closeAll, but we call it via the collateral).
        ICollateral collateral = c.controller().collateral();

        // Fully close the account; this clears the open position and sets the
        // liquidation flag so no new position can be opened.
        collateral.closeAll(account);

        // A fully closed account must not be liquidatable, since liquidatable
        // checks whether collateral can cover maintenance risk.
        bool liquidatableAfter = collateral.liquidatable(account, IProduct(address(c)));

        // The general rule: after closeAll, the account is not liquidatable.
        assert(!liquidatableAfter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account) public {
        // closeAll can only be called by the collateral contract
        ICollateral collateral = c.controller().collateral();

        // The product must be closed from the caller's perspective for closeAll to be valid.
        // We read the closed flag before and after; the rule we assert is about the resulting state.
        bool closedBefore = c.closed();

        // We cannot directly call c.closeAll(account) because msg.sender here is this test contract,
        // not the collateral. But we can still exercise the rule through the product's own logic:
        // closing all via closeAll sets liquidation = true and clears the position.
        // Since msg.sender must be collateral, we instead use the fact that closeAll is only callable
        // by collateral and test the observable consequence on the product's account state.
        //
        // The only external entry that the collateral itself would call is c.closeAll(account),
        // but we cannot impersonate the collateral. Therefore we drive the product through
        // closeMakeFor / closeTakeFor? Those are not allowed to liquidate.
        //
        // We need a rule that holds for the product's public surface without requiring
        // msg.sender to be collateral. A useful general rule is about the closed flag:
        // updateClosed can only be called by the product owner (coordinator owner), so we
        // cannot call it. Instead we assert a rule that is true for all inputs to a
        // public function we can call: closeAll reverts when called by non-collateral.
        //
        // But the rule we want to keep: after closeAll, account is not liquidatable.
        // Since we cannot call closeAll, we instead check the converse: an account that is
        // liquidating (liquidation = true) is never liquidatable.
        // However, we have no way to set liquidation = true without closeAll.
        //
        // Given the allowed public surface, the only state we can observe about an account
        // is via c.isLiquidating(account), c.isClosed(account), c.maintenance(account),
        // c.position(account), c.pre(account), and the collateral's liquidatable view.
        // The collateral's liquidatable is a view on the collateral contract and takes
        // an IProduct; we can call it. It does not require msg.sender to be collateral.
        // The rule: if c.isLiquidating(account) is true, then the account is fully closed
        // and thus liquidatable should be false (because maintenance is zero).
        //
        // We can set isLiquidating to true only through closeAll, which we cannot call.
        // So we cannot reach a state where isLiquidating is true from a fresh contract.
        // Therefore the rule must be about a state we can reach: an account with zero
        // position is not liquidatable.
        //
        // After a fresh deployment, no account has a position, so collateral.liquidatable(account, product)
        // is false. That is trivially true for any account and any product state, but it is
        // a general rule about the interaction between the product and collateral:
        // an account with no maker/taker position has no maintenance and thus is not liquidatable.
        //
        // We can assert: liquidatable(account, c) == false whenever c.position(account).maker == 0
        // and c.position(account).taker == 0 and c.maintenance(account) == 0.
        // But the assert must be reached and the rule must be non-trivial for a faulty P.
        //
        // A faulty P could report a non-zero maintenance for an empty position or
        // the collateral could incorrectly report liquidatable = true for zero maintenance.
        // So the rule: for any account, if maintenance(account) == 0 then liquidatable(account, c) == false.
        // This is checkable without calling closeAll and holds for all inputs if P is correct.

        UFixed18 maint = c.maintenance(account);
        bool liquidatable = collateral.liquidatable(account, c);

        // General rule: zero maintenance implies not liquidatable.
        assert(!(maint == UFixed18Lib.ZERO) || !liquidatable);
    }

    receive() external payable {}
}

