contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 openAmt, uint256 closeAmt) public {
        require(openAmt > 0);

        bool openReverted;
        try c.openMake(UFixed18.wrap(openAmt)) {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        if (openReverted) {
            assert(true);
            return;
        }

        uint256 v = c.latestVersion();
        Position memory before = c.positionAtVersion(v);

        bool closeReverted;
        if (closeAmt > 0) {
            try c.closeMake(UFixed18.wrap(closeAmt)) {
                closeReverted = false;
            } catch {
                closeReverted = true;
            }
        } else {
            closeReverted = true;
        }

        if (closeReverted) {
            assert(true);
            return;
        }

        Position memory next = c.pre();
        uint256 expectedMaker = UFixed18.unwrap(before.maker) + openAmt - closeAmt;
        assert(UFixed18.unwrap(next.openPosition.maker) == expectedMaker);
    }
}

