contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 makerAmount, uint256 takeAmount, uint256 closeAmount) public {
        require(makerAmount > 0);
        require(takeAmount > 0);
        require(closeAmount > 0);

        UFixed18 maker = UFixed18Lib.from(makerAmount);
        UFixed18 take = UFixed18Lib.from(takeAmount);
        UFixed18 close = UFixed18Lib.from(closeAmount);

        c.openMake(maker);
        c.openTake(take);

        Position memory before = c.position(address(this));

        bool reverted;
        try c.closeTakeFor(address(this), close) {
            reverted = false;
        } catch {
            reverted = true;
        }

        Position memory afterPos = c.position(address(this));

        assert(reverted || afterPos.taker.lte(before.taker));
    }

    receive() external payable {}
}

