contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool pause) public payable {
        require(amount > 0);

        // Initialize the product so calls have a chance to succeed/revert correctly
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.VANILLA,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.POSITIVE,
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(address(0));
        info.maintenance = UFixed18Lib.ZERO;
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.MAX;
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18Lib.from(0),
            maxRate: PackedFixed18Lib.from(0),
            targetRate: PackedFixed18Lib.from(0),
            targetUtilization: PackedUFixed18Lib.from(UFixed18Lib.ONE)
        });

        c.initialize(info);

        uint256 before = c.latestVersion();

        bool reverted;
        if (pause) {
            try c.updateClosed(true) { reverted = false; } catch { reverted = true; }
        } else {
            try c.openTake(UFixed18Lib.from(amount)) { reverted = false; } catch { reverted = true; }
        }

        uint256 after_ = c.latestVersion();

        if (pause) {
            assert(reverted || after_ == before);
        } else {
            assert(reverted || after_ >= before);
        }
    }
}

