contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");

        // Read the initial closed state through the public getter.
        bool wasClosed = c.closed();

        // Attempt to open a take position.
        bool reverted;
        try c.openTake(UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: openTake reverts iff the product was closed.
