contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount, uint256 priceSeed) public payable {
        require(account != address(0));
        require(account != address(this));

        // Use amount as a UFixed18 amount; ensure nonzero so openTakeFor does not silently no-op
        UFixed18 takeAmount = UFixed18.wrap(amount);
        require(amount > 0);

        // Read whether the account is liquidating before opening; the rule should hold for non-liquidating accounts
        bool wasLiquidating = c.isLiquidating(account);
        require(!wasLiquidating);

        // Record pre-position before the action
        PrePosition memory preBefore = c.pre(account);

        // The deciding call: open a take position for the account. This may revert (e.g. if closed, paused,
        // insufficient collateral, oracle bootstrapping, over limit, double-sided, etc.). Capture the revert flag.
        bool reverted;
        try c.openTakeFor(account, takeAmount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            // If the call succeeded, the account's pre-position must have been advanced to the latest
            // oracle version (the version used by openTakeFor), and the pre open-taker amount must have
            // increased by exactly the requested amount. We observe the account's pre() and its next
            // position via positionAtVersion(latestVersion()).next(pre()).
            PrePosition memory preAfter = c.pre(account);

            // The account must not be double-sided after a successful openTake — opening a taker position
            // when the account is already a maker should revert (ProductDoubleSidedError), so success
            // implies the next position has zero maker side.
            Position memory next = c.positionAtVersion(c.latestVersion()).next(preAfter);

            // Rule: successful openTakeFor(account, amount) with amount > 0 implies the next position
            // has a taker amount >= amount (>= because it accumulates with any existing taker) and
            // zero maker. This is a general invariant over all accounts and amounts that do not revert.
            assert(next.maker == UFixed18.wrap(0) && next.taker >= takeAmount);
        } else {
            // If the call reverted, the account's pre-position must be unchanged, i.e. no partial state
            // mutation occurred. This is a general no-side-effect-on-revert rule.
            PrePosition memory preAfter = c.pre(account);
            assert(preAfter.openPosition.maker == preBefore.openPosition.maker &&
                   preAfter.openPosition.taker == preBefore.openPosition.taker &&
                   preAfter.closePosition.maker == preBefore.closePosition.maker &&
                   preAfter.closePosition.taker == preBefore.closePosition.taker);
        }
    }
}

