contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 closeFirst) public payable {
        // closeFirst is unused; included as a parameter to satisfy the template.
        // The property is about calling an opening function while closed.

        // Close the product via its public surface. updateClosed is external and onlyProductOwner,
        // but in this test the InvMutTest contract is the owner (it deployed c).
        // Note: updateClosed itself calls _settle() which may revert if the oracle isn't ready,
        // so we tolerate that by checking the revert flag rather than assuming success.
        bool closeReverted;
        try c.updateClosed(true) { closeReverted = false; } catch { closeReverted = true; }

        // Only proceed with the rule when closing succeeded; otherwise the precondition
        // (product is closed) cannot be established and the rule's antecedent is false.
        bool closed = c.closed();

        // Attempt to open a make position while closed. This must revert with ProductClosedError.
        bool openMakeReverted = true;
        try c.openMakeFor(address(this), 1) {
            openMakeReverted = false;
        } catch {
            openMakeReverted = true;
        }

        // General rule: if the product is closed, then opening new positions must revert.
        // (The `closed` observed after updateClosed is the same value the guard notClosed uses.)
        assert(!closed || (closeReverted ? true : openMakeReverted));
    }

    receive() external payable {}
}

