contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");

        // This test does not need Ether, but if setup calls on c required value they would use
        // a parameter amount and require(address(this).balance >= amount) first.

        uint256 beforeTaker = c.position(address(this)).taker;
        uint256 beforeVersion = c.latestVersion(address(this));

        bool reverted;
        try c.openTake(UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTaker = c.position(address(this)).taker;
        uint256 afterVersion = c.latestVersion(address(this));

        // If the call succeeded, the account's taker position must have increased by exactly
        // the requested amount (normalized/equal to what the pre-position recorded), and the
        // account's latest version must have advanced at least to the version used.
        if (!reverted) {
            assert(afterTaker >= beforeTaker);
            assert(afterTaker - beforeTaker == amount || afterVersion > beforeVersion);
        } else {
            // On revert, the account position must be unchanged.
            assert(afterTaker == beforeTaker);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
