        } catch {
            reverted = true;
        }

        uint256 afterTaker = UFixed18.unwrap(c.position(address(this)).taker);
        uint256 afterVersion = c.latestVersion(address(this));

        assert(afterVersion >= beforeVersion);
        if (reverted) {
            assert(afterTaker == beforeTaker);
        } else {
            assert(afterTaker >= beforeTaker);
        }
    }

